package com.dongwon.sleeptimeline;
import android.app.*;import android.app.usage.*;import android.content.*;import android.content.pm.*;import android.os.*;import org.json.*;import java.util.*;
public class UsageReader {
 public static boolean allowed(Context c){AppOpsManager o=(AppOpsManager)c.getSystemService(Context.APP_OPS_SERVICE);return o.checkOpNoThrow(AppOpsManager.OPSTR_GET_USAGE_STATS,android.os.Process.myUid(),c.getPackageName())==AppOpsManager.MODE_ALLOWED;}
 public static List<SleepLogic.Event> events(Context c,long s,long e){List<SleepLogic.Event> out=new ArrayList<SleepLogic.Event>();if(!allowed(c))return out;UsageStatsManager m=(UsageStatsManager)c.getSystemService(Context.USAGE_STATS_SERVICE);UsageEvents v=m.queryEvents(s,e);if(v==null)return out;UsageEvents.Event r=new UsageEvents.Event();while(v.hasNextEvent()){v.getNextEvent(r);out.add(new SleepLogic.Event(r.getTimeStamp(),r.getEventType(),r.getPackageName()));}return out;}
 // 수면 구간을 찾을 때 사용으로 보지 않는 화면: 시스템 UI(잠금 화면·알림창)와 홈 화면(런처).
 static Set<String> notUse(Context c){Set<String> out=new HashSet<String>(Arrays.asList("com.android.systemui","android","com.sec.android.app.launcher","com.google.android.apps.nexuslauncher"));try{for(android.content.pm.ResolveInfo r:c.getPackageManager().queryIntentActivities(new Intent(Intent.ACTION_MAIN).addCategory(Intent.CATEGORY_HOME),0))out.add(r.activityInfo.packageName);}catch(Exception ignored){}out.remove(c.getPackageName());return out;}
 // awakeNow: 앱을 열어 둔 상태에서 호출(지금 깨어 있음). 백그라운드 수집은 false.
 public static int capture(Context c,boolean awakeNow){if(!allowed(c))return 0;long now=System.currentTimeMillis();List<SleepLogic.Event> v=events(c,now-7L*86400000,now);Store d=new Store(c);try{d.propose(SleepLogic.awakeGaps(v,now-7L*86400000,now,awakeNow,notUse(c)),now);}finally{d.close();}return v.size();}
 public static List<SleepLogic.Gap> awakeGaps(Context c,boolean awakeNow){long now=System.currentTimeMillis();return SleepLogic.awakeGaps(events(c,now-8L*86400000,now),now-8L*86400000,now,awakeNow,notUse(c));}
 public static JSONObject usage(Context c,long start)throws Exception{Calendar cal=Calendar.getInstance();cal.setTimeInMillis(start);cal.set(Calendar.HOUR_OF_DAY,0);cal.set(Calendar.MINUTE,0);cal.set(Calendar.SECOND,0);cal.set(Calendar.MILLISECOND,0);start=cal.getTimeInMillis();cal.add(Calendar.DATE,1);long end=Math.min(cal.getTimeInMillis(),System.currentTimeMillis());JSONObject obj=new JSONObject();JSONArray hourly=new JSONArray(),apps=new JSONArray();boolean old=start<System.currentTimeMillis()-7L*86400000;obj.put("available",allowed(c)&&!old&&start<end);if(!obj.getBoolean("available"))return obj.put("hours",hourly).put("apps",apps).put("total",0);List<SleepLogic.Event> raw=events(c,start-86400000,end);List<SleepLogic.Session> sessions=SleepLogic.sessions(raw,start,end);long[] buckets=new long[24];String[] top=new String[24];Map<String,Long> totals=new HashMap<String,Long>();List<Map<String,Long>> byHour=new ArrayList<Map<String,Long>>();for(int i=0;i<24;i++)byHour.add(new HashMap<String,Long>());for(SleepLogic.Session s:sessions){long p=s.start;if(s.end<=p||p<start)continue;totals.put(s.pkg,totals.containsKey(s.pkg)?totals.get(s.pkg)+s.end-p:s.end-p);while(p<s.end){Calendar h=Calendar.getInstance();h.setTimeInMillis(p);int hour=h.get(Calendar.HOUR_OF_DAY);h.set(Calendar.MINUTE,0);h.set(Calendar.SECOND,0);h.set(Calendar.MILLISECOND,0);h.add(Calendar.HOUR_OF_DAY,1);long until=Math.min(h.getTimeInMillis(),s.end),dur=until-p;if(dur<=0)break;buckets[hour]+=dur;Map<String,Long> map=byHour.get(hour);map.put(s.pkg,map.containsKey(s.pkg)?map.get(s.pkg)+dur:dur);p=until;}}long total=0;for(int i=0;i<24;i++){long best=0;top[i]="";JSONArray detail=new JSONArray();for(Map.Entry<String,Long> a:byHour.get(i).entrySet()){detail.put(new JSONObject().put("pkg",a.getKey()).put("name",label(c,a.getKey())).put("ms",a.getValue()));if(a.getValue()>best){best=a.getValue();top[i]=a.getKey();}}hourly.put(new JSONObject().put("ms",buckets[i]).put("pkg",top[i]).put("apps",detail));total+=buckets[i];}List<Map.Entry<String,Long>> sorted=new ArrayList<Map.Entry<String,Long>>(totals.entrySet());Collections.sort(sorted,new Comparator<Map.Entry<String,Long>>(){public int compare(Map.Entry<String,Long>a,Map.Entry<String,Long>b){return Long.compare(b.getValue(),a.getValue());}});for(Map.Entry<String,Long>a:sorted)apps.put(new JSONObject().put("pkg",a.getKey()).put("name",label(c,a.getKey())).put("ms",a.getValue()));return obj.put("hours",hourly).put("apps",apps).put("total",total);}
 static String label(Context c,String p){try{return c.getPackageManager().getApplicationLabel(c.getPackageManager().getApplicationInfo(p,0)).toString();}catch(Exception e){return p;}}
}
